CREATE OR REPLACE FUNCTION buildpulse_verify_story(p_story_id UUID,p_reviewer TEXT,p_canonical_source_url TEXT,p_notes TEXT DEFAULT NULL,p_evidence_urls TEXT[] DEFAULT ARRAY[]::TEXT[]) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u TEXT; old_state TEXT; BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'service role required'; END IF; IF coalesce(trim(p_reviewer),'')='' THEN RAISE EXCEPTION 'reviewer required'; END IF; IF p_canonical_source_url !~ '^https://' THEN RAISE EXCEPTION 'HTTPS canonical source required'; END IF; SELECT verification_state INTO old_state FROM buildpulse_stories WHERE id=p_story_id FOR UPDATE; IF old_state IS NULL THEN RETURN FALSE; END IF; IF old_state NOT IN ('pending','needs_review') THEN RAISE EXCEPTION 'story is not reviewable'; END IF; UPDATE buildpulse_stories SET verification_state='verified',verified_at=NOW(),verified_by=lower(trim(p_reviewer)),canonical_source_url=p_canonical_source_url,verification_notes=p_notes,corroboration_count=coalesce(array_length(p_evidence_urls,1),0) WHERE id=p_story_id; INSERT INTO buildpulse_story_evidence(story_id,source_url,source_kind,notes) VALUES(p_story_id,p_canonical_source_url,'primary','Canonical verification source') ON CONFLICT(story_id,source_url) DO UPDATE SET source_kind='primary'; FOREACH u IN ARRAY p_evidence_urls LOOP IF u ~ '^https://' AND u<>p_canonical_source_url THEN INSERT INTO buildpulse_story_evidence(story_id,source_url,source_kind,notes) VALUES(p_story_id,u,'supporting','Verification evidence') ON CONFLICT(story_id,source_url) DO NOTHING; END IF; END LOOP; INSERT INTO buildpulse_review_events(story_id,action,actor,notes) VALUES(p_story_id,'verify',lower(trim(p_reviewer)),p_notes); RETURN TRUE; END $$; REVOKE ALL ON FUNCTION buildpulse_verify_story(UUID,TEXT,TEXT,TEXT,TEXT[]) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION buildpulse_verify_story(UUID,TEXT,TEXT,TEXT,TEXT[]) TO service_role;